{
  "summary": "Before proceeding to Step 2, ensure your HFE is still valid, confirm no changes to your personal or financial details, and gather all required documents.",
  "claims": [
    {
      "claim_id": "c1",
      "kind": "policy_fact",
      "text": "The HFE (Housing Flat Eligibility) letter is valid for 12 months from the issue date, provided there are no material changes to your household profile."
    },
    {
      "claim_id": "c2",
      "kind": "preparation_step",
      "text": "Verify that your HFE issued on 25 October 2026 is still within its 12‑month validity period before you submit Step 2 on 15 November 2026."
    },
    {
      "claim_id": "c3",
      "kind": "preparation_step",
      "text": "Check that neither of you has acquired any private property, received any other HDB flat or subsidy, or experienced a change in citizenship status since the HFE was issued."
    },
    {
      "claim_id": "c4",
      "kind": "preparation_step",
      "text": "If any of the above circumstances have changed, you must inform HDB and may need to re‑apply for a new HFE before proceeding to Step 2."
    },
    {
      "claim_id": "c5",
      "kind": "preparation_step",
      "text": "Gather the required supporting documents for Step 2, such as NRIC copies, marriage certificate, latest payslips, and CPF statements."
    },
    {
      "claim_id": "c6",
      "kind": "preparation_step",
      "text": "Ensure your latest income information is up to date; if your monthly income has changed since Step 1, be prepared to declare the new figure in Step 2."
    },
    {
      "claim_id": "c7",
      "kind": "caveat",
      "text": "Policy details may be updated; always confirm the latest Step‑2 requirements on the official HDB website (hdb.gov.sg) or the HDB Flat Portal."
    }
  ],
  "missing_profile_fields": [],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}
